 useEffect(()=>{if(!boardPage||!data?.board||body)return;let saved='';try{saved=localStorage.getItem(activeDraftKey)||'';}catch{}if(!saved)return;const timer=window.setTimeout(()=>setBody(saved),0);return()=>window.clearTimeout(timer);},[boardPage,data?.board,activeDraftKey,body]);
 function updateUpload(key:string,change:(job:UploadJob)=>UploadJob){setUploads(current=>current[key]?{...current,[key]:change(current[key])}:current);}
 function reportUpload(key:string,progress:number){const next=Math.max(0,Math.min(99,Math.round(progress)));uploadPercents.current[key]=Math.max(uploadPercents.current[key]||0,next);if(uploadFrames.current[key])return;uploadFrames.current[key]=requestAnimationFrame(()=>{const value=uploadPercents.current[key]||0;delete uploadFrames.current[key];updateUpload(key,job=>({...job,progress:value,status:'uploading'}));});}
 function resumeStorageKey(){return 'line-rangers-community-upload-resume';}
 function isResumeRecord(value:unknown):value is ResumeRecord{if(!value||typeof value!=='object'||Array.isArray(value))return false;const record=value as Record<string,unknown>;return typeof record.request==='string'&&typeof record.board==='string'&&typeof record.name==='string'&&typeof record.type==='string'&&Number.isSafeInteger(record.size)&&Number.isSafeInteger(record.lastModified)&&typeof record.body==='string';}
 function savedResumes(){try{const parsed=JSON.parse(localStorage.getItem(resumeStorageKey())||'{}') as unknown;if(isResumeRecord(parsed))return {[parsed.request]:parsed};if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))return {};return Object.fromEntries(Object.entries(parsed).filter(([,record])=>isResumeRecord(record))) as Record<string,ResumeRecord>;}catch{return {};}}
 function saveResume(job:UploadJob){try{const resumes=savedResumes();resumes[job.request]={request:job.request,board:job.board,name:job.name,type:job.type,size:job.size,lastModified:job.file?.lastModified||0,body:job.body};localStorage.setItem(resumeStorageKey(),JSON.stringify(resumes));}catch{}}
 function clearResume(request:string){try{const resumes=savedResumes();delete resumes[request];if(Object.keys(resumes).length)localStorage.setItem(resumeStorageKey(),JSON.stringify(resumes));else localStorage.removeItem(resumeStorageKey());}catch{}}
 function resumeForReselectedFile(next:File){return Object.values(savedResumes()).find(saved=>saved.board===data?.board&&saved.name===next.name&&saved.type===next.type&&saved.size===next.size&&saved.lastModified===next.lastModified)||null;}
 function finishMediaBatch(success:boolean){const batch=mediaBatch.current;if(!batch)return;batch.remaining-=1;batch.failed ||= !success;if(batch.remaining>0)return;mediaBatch.current=null;if(!batch.failed&&bodyRef.current.trim()===batch.body)setDraft('');}
 function uploadPart(sessionId:string,part:number,chunk:Blob,onProgress:(loaded:number)=>void,signal?:AbortSignal){return new Promise<void>((resolve,reject)=>{const xhr=new XMLHttpRequest();let settled=false;const cleanup=()=>{signal?.removeEventListener('abort',abort);};const finish=(error?:Error)=>{if(settled)return;settled=true;cleanup();if(error)reject(error);else resolve();};const abort=()=>{xhr.abort();finish(new Error('unavailable'));};xhr.open('PUT','/api/upload/part?'+new URLSearchParams({id:sessionId,part:String(part)}));xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.timeout=communityTimeouts.videoPartMs;xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(e.loaded);};xhr.onload=()=>{let j:{error?:string}={};try{j=JSON.parse(xhr.responseText||'{}');}catch{}if(xhr.status>=200&&xhr.status<300)finish();else finish(new Error(j.error||'unavailable'));};xhr.onerror=()=>finish(new Error('unavailable'));xhr.ontimeout=()=>finish(new Error('unavailable'));xhr.onabort=()=>finish(new Error('unavailable'));if(signal){if(signal.aborted)return abort();signal.addEventListener('abort',abort,{once:true});}xhr.send(chunk);});}
 async function retryFetch(url:string,init:RequestInit,timeout:number,attempts=3){let last:unknown;for(let attempt=0;attempt<attempts;attempt++){try{const response=await fetch(url,{...init,signal:AbortSignal.timeout(timeout)});if(response.status>=500&&attempt<attempts-1){await response.body?.cancel();await new Promise(resolve=>setTimeout(resolve,750*(attempt+1)));continue;}return response;}catch(e){last=e;if(attempt<attempts-1)await new Promise(resolve=>setTimeout(resolve,750*(attempt+1)));}}throw last instanceof Error?last:new Error('unavailable');}
 function appendUploadedVideo(job:UploadJob,id:string){const me=data?.me;if(!me)return;const post:Post={id,name:me.name,role:me.role,body:job.body,video:null,mediaType:job.type,mediaName:job.name,mediaSize:job.size,mediaGroup:job.group,created:Date.now(),likes:0,liked:0,replies:0,pinned:0,helpful:0,helped:false,title:null};setData(current=>!current||current.board!==job.board||current.posts.some(item=>item.id===id)?current:{...current,posts:[post,...current.posts],stats:{...current.stats,videos:current.stats.videos+1,latestCreated:Math.max(current.stats.latestCreated,post.created)}});}
 async function uploadVideo(fileToSend:File,job:UploadJob){const started=performance.now();let partController:AbortController|undefined;try{updateUpload(job.key,current=>({...current,status:'preparing',error:undefined,file:fileToSend}));const sessionResponse=await retryFetch('/api/upload/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({board:job.board,body:job.body,group:job.group,request:job.request,name:fileToSend.name,type:fileToSend.type,size:fileToSend.size})},communityTimeouts.videoSessionMs);let session:{ok?:boolean;error?:string;id?:string;partSize?:number;parts?:number;uploadedParts?:number[];status?:string};try{session=await sessionResponse.json() as typeof session;}catch{throw new Error('unavailable');}if(!sessionResponse.ok)throw new Error(session.error||'unavailable');if(session.status==='completed'&&session.id){appendUploadedVideo(job,session.id);setUploads(current=>{const next={...current};delete next[job.key];return next;});clearResume(job.request);finishMediaBatch(true);metric('upload_complete',started,true);return;}const partSize=session.partSize;if(!session.id||!partSize||!session.parts)throw new Error('unavailable');metric('upload_start',started,true);saveResume(job);const completed=new Set(session.uploadedParts||[]);let transferred=0;for(const part of completed){const start=(part-1)*partSize;transferred+=Math.min(partSize,fileToSend.size-start);}reportUpload(job.key,(transferred/fileToSend.size)*100);updateUpload(job.key,current=>({...current,status:'uploading',progress:Math.round((transferred/fileToSend.size)*100)}));const missing=Array.from({length:session.parts},(_,index)=>index+1).filter(part=>!completed.has(part));let nextPart=0;partController=new AbortController();const sendPart=async()=>{for(;;){const part=missing[nextPart++];if(!part)return;const start=(part-1)*partSize;const chunk=fileToSend.slice(start,Math.min(start+partSize,fileToSend.size));let sent=false;for(let attempt=0;attempt<mediaPartAttempts&&!sent;attempt++){try{await uploadPart(session.id!,part,chunk,loaded=>reportUpload(job.key,((transferred+loaded)/fileToSend.size)*100),partController!.signal);sent=true;}catch(e){if(partController?.signal.aborted)throw e;if(attempt===mediaPartAttempts-1)throw e;await new Promise(resolve=>setTimeout(resolve,750*(attempt+1)));}}transferred+=chunk.size;reportUpload(job.key,(transferred/fileToSend.size)*100);}};try{await Promise.all([sendPart(),sendPart()]);}catch(e){partController.abort();throw e;}updateUpload(job.key,current=>({...current,status:'finalizing',progress:99}));const completeResponse=await retryFetch('/api/upload/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:session.id})},communityTimeouts.videoCompleteMs);let complete:{ok?:boolean;error?:string;id?:string};try{complete=await completeResponse.json() as typeof complete;}catch{throw new Error('unavailable');}if(!completeResponse.ok||!complete.id)throw new Error(complete.error||'unavailable');appendUploadedVideo(job,complete.id);setUploads(current=>{const next={...current};delete next[job.key];return next;});clearResume(job.request);finishMediaBatch(true);metric('upload_complete',started,true);setNotice(t.saved);}catch(e){partController?.abort();finishMediaBatch(false);metric('upload_complete',started,false,e);updateUpload(job.key,current=>({...current,status:'failed',error:e instanceof Error?e.message:'unavailable',file:fileToSend}));setNotice(errorText(e instanceof Error?e.message:'unavailable',lang));}}
 async function uploadImage(fileToSend:File,description:string,request:string,uploadBoard:string,group:string|null){const started=performance.now();try{const form=new FormData();form.set('board',uploadBoard);form.set('body',description);form.set('request',request);if(group)form.set('group',group);form.set('file',fileToSend);const r=await fetch('/api/upload',{method:'PUT',body:form,signal:AbortSignal.timeout(communityTimeouts.imageUploadMs)});const j=await r.json() as {id?:string;error?:string};if(!r.ok||!j.id)throw new Error(j.error||'unavailable');const me=data?.me;if(me){const post:Post={id:j.id,name:me.name,role:me.role,body:description,video:null,mediaType:fileToSend.type,mediaName:fileToSend.name,mediaSize:fileToSend.size,mediaGroup:group,created:Date.now(),likes:0,liked:0,replies:0,pinned:0,helpful:0,helped:false,title:null};setData(current=>!current||current.board!==uploadBoard?current:{...current,posts:[post,...current.posts],stats:{...current.stats,comments:current.stats.comments+1,todayComments:current.stats.todayComments+1,latestCreated:post.created}});}finishMediaBatch(true);metric('comment_post',started,true);setNotice(t.saved);}catch(e){finishMediaBatch(false);metric('comment_post',started,false,e);setFiles([fileToSend]);setNotice(errorText(e instanceof Error?e.message:'unavailable',lang));}}
 function startMediaUpload(){if(!files.length||replyTarget||!canUseFeature('commentsEnabled')||needsName()||!data?.board)return;if(files.some(file=>file.type.startsWith('video/'))&&!canUseFeature('videoUploadEnabled'))return;const uploadBoard=data.board;const description=body.trim();const group=files.length>1?requestUUID():null;mediaBatch.current={remaining:files.length,body:description,failed:false};setFiles([]);setPostType('text');setRequestId(requestUUID());files.forEach((fileToSend,index)=>{const request=index===0&&files.length===1?requestId:requestUUID();if(fileToSend.type.startsWith('video/')){const key='upload:'+request;const job:UploadJob={key,request,group,board:uploadBoard,name:fileToSend.name,type:fileToSend.type,size:fileToSend.size,body:description,created:Date.now(),progress:0,status:'preparing',file:fileToSend};setUploads(current=>({...current,[key]:job}));void uploadVideo(fileToSend,job);}else if(index===0)void uploadImage(fileToSend,description,request,uploadBoard,group);});}
