 async function publish(){const activeData=data;if(!canUseFeature('commentsEnabled')||needsName()||!activeData?.me||!activeData.board)return;if(Object.values(uploads).some(job=>job.status!=='failed')){setNotice('動画の投稿が完了するまで、次の投稿はお待ちください。');return;}if(!online){setNotice('現在オフラインです。入力内容はこの端末に残っています。');return;}const parent=replyTarget?.id||video||null;if(!parent&&postType==='media'){startMediaUpload();return;}const content=body.trim();if(!content||postSending)return;const request=requestId;const nested=!!replyTarget;const temp:Post={id:'local:'+request,name:activeData.me.name,role:activeData.me.role,body:content,video:null,mediaType:null,mediaName:null,mediaSize:null,created:Date.now(),likes:0,liked:0,replies:0,pinned:0,helpful:0,helped:false,title:null,localState:'sending',localRequest:request,localParent:parent};const local=insertLocalPost(temp,nested);setPostSending(true);try{const result=await boardRequest<{ok?:boolean;id?:string;error?:string}>({action:'post',board:activeData.board,parent,body:content,request},nested?'comment_reply':'comment_post');const savedId=result.id;if(!savedId)throw new Error('unavailable');updatePost(local.id,current=>({...current,id:savedId,localState:undefined}));if(bodyRef.current.trim()===content)setDraft('');setRequestId(requestUUID());setReplyTarget(null);setNotice(t.saved);}catch(e){rollbackLocalPost(local);setNotice(errorText(e instanceof Error?e.message:'unavailable',lang));}finally{setPostSending(false);}}
 async function retryPost(post:Post){const activeData=data;if(!canUseFeature('commentsEnabled')||!post.localRequest||!activeData?.board)return;const nested=!!post.localParent;const parent=post.localParent||null;const request=post.localRequest;const needsCount=!post.localCounted;const needsParentCount=!!post.localParent&&!post.localParentCounted;const retrying={...post,localState:'sending' as const,localCounted:true,localParentCounted:!!post.localParent};updatePost(post.id,()=>retrying);if(needsCount)adjustLocalCommentCount(1,post.created);if(needsParentCount&&post.localParent)updatePost(post.localParent,current=>({...current,replies:current.replies+1}));try{const result=await boardRequest<{ok?:boolean;id?:string;error?:string}>({action:'post',board:activeData.board,parent,body:retrying.body,request},nested?'comment_reply':'comment_post');const savedId=result.id;if(!savedId)throw new Error('unavailable');updatePost(retrying.id,current=>({...current,id:savedId,localState:undefined}));setNotice(t.saved);}catch(e){rollbackLocalPost(retrying);setNotice(errorText(e instanceof Error?e.message:'unavailable',lang));}}
